// Lee las respuestas del formulario y arma una recomendación.
// Los nombres de los campos (nombre, idea, nivel) son los «Field Name» del formulario.
const { nombre, idea, nivel } = $input.first().json;

// Pasamos la idea a minúsculas y sin tildes para buscar palabras clave.
const texto = String(idea).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Cada tema tiene palabras (o el comienzo de una palabra) y el workflow por donde seguir.
const temas = [
  { tema: 'IA', palabras: ['ia', 'agente', 'chat', 'asistente', 'bot', 'pregunt'], workflow: '05-agente-ia' },
  { tema: 'Avalanche Fuji', palabras: ['fuji', 'avalanche', 'blockchain', 'wallet', 'pago', 'token', 'cripto'], workflow: '12-fuji-leer-transaccion' },
  { tema: 'login de usuarias', palabras: ['login', 'sesion', 'usuari', 'registr', 'cuenta'], workflow: '21-clerk-api-protegida' },
  { tema: 'guardar datos', palabras: ['guardar', 'base de datos', 'tabla', 'inventario', 'lista'], workflow: '30-formulario-a-supabase' },
];
// \b marca el comienzo de una palabra: así «ia» no aparece dentro de «familia».
const elegido = temas.find((t) => t.palabras.some((p) => new RegExp('\\b' + p).test(texto)));

// El workflow del tema (o el de formularios, si la idea no nombra ningún tema).
const delTema = elegido ? elegido.workflow : '04-formulario';

// El orden depende del nivel que eligió la persona.
let primerPaso = '01-hola-n8n';
let siguiente = delTema;
if (nivel === 'Ya armé algún workflow') primerPaso = '03-http-request';
if (nivel === 'Lo uso seguido') {
  primerPaso = delTema;
  siguiente = 'una guía de proyecto del repo «guias»';
}

return [
  {
    json: {
      nombre: String(nombre).trim(),
      idea,
      nivel,
      tema: elegido ? elegido.tema : 'automatización',
      primer_paso: primerPaso,
      siguiente,
    },
  },
];

